// Assemble the Fieldnote Coffee Roasters theme (6 Divi 5 pages for an independent coffee roaster and cafe) into one pack. Unlike create-real-estate-pack.ts the pages are NOT
// generated by the pipeline's Claude workers: they are composed by the AI Editor for
// Divi 5 plugin from its section recipes (design language organic-warm + a style kit,
// validated by the real LayoutGate) in the validator repo:
//   php scripts/theme-packs/build.php fieldnote     -> dist/theme-packs/fieldnote/<role>.json
// and then run through every downstream gate here (validate, stock photos, design lint,
// mobile stacking, dedupe, SEO, real Divi render, critics, ingest).
//
//   npm run dev            # in another shell (ingest target)
//   set -a && . ./.env.local && set +a && FLD_DIR=<dir with the six json files> npx tsx scripts/create-fieldnote-pack.ts
// Smoke test: THEME_ONLY_ROLES=home.
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { eq, inArray } from 'drizzle-orm';
import { db } from '@/db/client';
import { packs, packLayouts, layouts } from '@/db/schema';
import { buildThemeDeps } from '@/pipeline/deps';
import { runThemePack, themePageSlug, type ThemeSpec, type ThemePage } from '@/pipeline/theme';
import type { Brief } from '@/pipeline/compose';

const DIR = process.env.FLD_DIR ?? '../Divi 5 Deterministic Validator/dist/theme-packs/fieldnote';

const BRIEF: Brief = {
  businessType: 'ecommerce',
  businessName: 'Fieldnote Coffee Roasters',
  tagline: 'Roasted this week. Not this year.',
  audience: 'coffee lovers who want freshly roasted single origins and blends, delivered or poured at the cafe, from a small independent roaster',
  conversionGoal: 'start a coffee subscription',
  primaryCta: 'Shop the coffee',
  accentColorHex: '#FF3B00',
  voice: 'blunt, witty and plain-spoken. Short sentences, concrete facts and a dry sense of humour, never precious.',
  palette: { primary: '#ff3b00', secondary: '#4a4a4a', tint: '#e8e4da', dark: '#000000', heading: '#000000', body: '#4a4a4a' },
  designNotes: 'Brutalist-flat design language: paper background, thick black borders, square corners, no shadows, a heavy Archivo headline in capitals, Space Mono labels and one orange accent.',
};

const BRAND_FACTS =
  'Fieldnote Coffee Roasters, 418 Washington Avenue N, Minneapolis, MN 55401. Phone (612) 555-0139. hello@fieldnote.coffee. ' +
  'Sample copy: names, prices and reviews are examples to replace.';

const ROLES: { role: string; roleLabel: string }[] = [
  { role: 'home', roleLabel: 'Home' },
  { role: 'coffee', roleLabel: 'Coffee' },
  { role: 'subscribe', roleLabel: 'Subscribe' },
  { role: 'cafe', roleLabel: 'The Cafe' },
  { role: 'roastery', roleLabel: 'The Roastery' },
  { role: 'contact', roleLabel: 'Contact' },
];

const PAGES: ThemePage[] = ROLES.map((r) => ({
  ...r,
  flow: [],
  precomposed: readFileSync(`${DIR}/${r.role}.json`, 'utf8'),
}));

const SPEC: ThemeSpec = { niche: 'coffee', style: 'brutalist', color: 'orange', brief: BRIEF, brandFacts: BRAND_FACTS, pages: PAGES };

const PACK_SLUG = 'fieldnote-coffee-roaster-theme';
const PACK_TITLE = 'Fieldnote: Coffee Roaster & Cafe Theme (6 Pages)';
const PRICE_CENTS = 1200;
const DESCRIPTION =
  'A complete six-page Divi 5 website for an independent coffee roaster, cafe or any craft food and drink brand, ready ' +
  'to make your own. Home, Coffee, Subscribe, The Cafe, The Roastery and Contact share one raw, confident identity: a ' +
  'paper background, thick black borders, square corners, a heavy headline in capitals, mono labels and a single orange ' +
  'accent. Every section is built from proven, validated recipes and a single design language and style kit, so ' +
  'buttons, accordions, forms and type match on every page, on desktop, tablet and phone. A bordered hero, a coffees ' +
  'grid, a brew guide, subscription pricing with a comparison table, a cafe page, a roastery story with a team and ' +
  'founder note, FAQs and a contact form with the shop details are all in place. Names, prices, hours and reviews are ' +
  'sample copy: swap in your own and publish. No lorem ipsum, no broken layouts. One simple commercial license, ' +
  'unlimited client sites.';
const PACK_SEO = {
  metaTitle: 'Fieldnote: Coffee Roaster Theme for Divi 5 (6 Pages) | Divi5Lab',
  metaDescription:
    'A complete six-page Divi 5 website theme for a coffee roaster or cafe: Home, Coffee, Subscribe, The Cafe, The ' +
    'Roastery and Contact. One bold brand, real copy, subscription pricing and brew guide sections.',
  keywords: [
    'divi 5 coffee roaster theme', 'coffee shop website template', 'cafe divi template', 'coffee subscription divi 5',
    'brutalist divi 5 theme', 'divi 5 multi-page theme',
  ],
};

async function upsertPack(slugs: string[]): Promise<void> {
  const rows = await db
    .select({ id: layouts.id, slug: layouts.slug, previews: layouts.previewImageKeys })
    .from(layouts).where(inArray(layouts.slug, slugs));
  const bySlug = new Map(rows.map((r) => [r.slug, r]));
  const found = slugs.filter((s) => bySlug.has(s));
  if (found.length === 0) { console.error('no Fieldnote pages found in DB — did ingest run?'); process.exitCode = 1; return; }
  if (found.length < slugs.length) console.warn(`only ${found.length}/${slugs.length} pages present; linking what exists`);

  const cover = bySlug.get(slugs[0])?.previews?.[0] ?? bySlug.get(found[0])!.previews?.[0] ?? null;
  const existing = (await db.select().from(packs).where(eq(packs.slug, PACK_SLUG)).limit(1))[0];
  const common = {
    title: PACK_TITLE, description: DESCRIPTION, kind: 'paid' as const,
    priceCents: PRICE_CENTS, stripePriceId: null, coverImageKey: cover, seo: PACK_SEO, status: 'published' as const,
  };
  let packId: string;
  if (existing) {
    packId = existing.id;
    await db.update(packs).set(common).where(eq(packs.id, packId));
  } else {
    packId = randomUUID();
    await db.insert(packs).values({ id: packId, slug: PACK_SLUG, ...common });
  }

  await db.delete(packLayouts).where(eq(packLayouts.packId, packId));
  await db.insert(packLayouts).values(found.map((s, i) => ({ packId, layoutId: bySlug.get(s)!.id, position: i })));

  console.log(`\nPack ready: /packs/${PACK_SLUG}  (paid, ${found.length} pages, cover=${cover ? 'set' : 'none'})`);
}

async function main() {
  const { deps, close } = await buildThemeDeps({ businessName: BRIEF.businessName, logPrefix: '[theme]', defaultMaxBudgetUsd: 1 });

  // Optional smoke-test knob: THEME_ONLY_ROLES=home,listings limits which pages generate.
  const onlyRoles = (process.env.THEME_ONLY_ROLES ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  const spec: ThemeSpec = onlyRoles.length ? { ...SPEC, pages: SPEC.pages.filter((p) => onlyRoles.includes(p.role)) } : SPEC;

  console.log(`[theme] generating ${spec.pages.length} ${spec.niche} pages for "${BRIEF.businessName}"…`);
  const result = await runThemePack(spec, deps);
  await close();
  console.log('[theme] summary:', { generated: result.generated, ingested: result.ingested, dropped: result.dropped, deduped: result.deduped });

  if (onlyRoles.length) { console.log('[theme] partial run (THEME_ONLY_ROLES set) — skipping pack assembly'); return; }
  const expectedSlugs = SPEC.pages.map((p) => themePageSlug(BRIEF, SPEC, p));
  await upsertPack(expectedSlugs);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
